package ru.kstolu.app;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w390dp-h844dp-mdpi")
public class SelectionRetryUiTest {
 private org.robolectric.android.controller.ActivityController<MainActivity> controller;private MainActivity host;private SharedPreferences prefs;private final List<JSONObject> sent=Collections.synchronizedList(new ArrayList<>());private CountDownLatch gate;
 @Before public void setup()throws Exception{RuntimeEnvironment.getApplication().getSharedPreferences("settings",0).edit().clear().commit();ApiClient.configureForTests(url->{throw new AssertionError("Unexpected network: "+url);});controller=Robolectric.buildActivity(MainActivity.class).setup();host=controller.get();prefs=host.getSharedPreferences("settings",0);}
 @After public void close(){if(gate!=null)gate.countDown();controller.pause().stop().destroy();ApiClient.restoreTransport();}
 private void call(String name)throws Exception{Method m=MainActivity.class.getDeclaredMethod(name);m.setAccessible(true);m.invoke(host);}
 private TextView find(View v,String s){if(v instanceof TextView&&((TextView)v).getText().toString().equals(s))return (TextView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){TextView x=find(((ViewGroup)v).getChildAt(i),s);if(x!=null)return x;}return null;}
 private View root(){return host.getWindow().getDecorView();}
 private String inventory(){return "{\"kind\":\"inventory\",\"status\":\"ok\",\"products\":[\"Томаты\",\"Рис\"],\"region\":\"Россия\",\"currency\":\"RUB\",\"receiptPrices\":[]}";}
 private void review()throws Exception{prefs.edit().putString("reviewedInventory",inventory()).commit();call("reviewProducts");}
 private String done(){return "{\"status\":\"done\",\"result\":{\"status\":\"ok\",\"currency\":\"RUB\",\"recipes\":[{\"status\":\"ok\",\"title\":\"Рис с томатами\",\"servings\":2,\"ingredients\":[],\"steps\":[]}]}}";}
 private HttpURLConnection response(URL url,String text){return new HttpURLConnection(url){final ByteArrayOutputStream body=new ByteArrayOutputStream();public void disconnect(){}public void connect(){}public boolean usingProxy(){return false;}public OutputStream getOutputStream(){return body;}public int getResponseCode()throws IOException{if(body.size()>0)try{sent.add(new JSONObject(body.toString("UTF-8")));}catch(Exception e){throw new IOException(e);}if(gate!=null)try{if(!gate.await(4,TimeUnit.SECONDS))throw new IOException("test gate timeout");}catch(InterruptedException e){throw new IOException(e);}return 200;}public InputStream getInputStream(){return new ByteArrayInputStream(text.getBytes(StandardCharsets.UTF_8));}};}
 private void idleUntil(java.util.function.BooleanSupplier condition)throws Exception{for(int i=0;i<400&&!condition.getAsBoolean();i++){Thread.sleep(10);Shadows.shadowOf(Looper.getMainLooper()).idle();}assertTrue("UI condition timed out",condition.getAsBoolean());}
 private boolean busy(){try{Field f=MainActivity.class.getDeclaredField("busy");f.setAccessible(true);return f.getBoolean(host);}catch(Exception e){throw new AssertionError(e);}}
 @Test public void processingIsVisibleAtButtonAndDoubleTapDoesNotSendTwice()throws Exception{review();gate=new CountDownLatch(1);ApiClient.configureForTests(url->response(url,done()));TextView button=find(root(),"Всё верно — составить блюда");button.performClick();assertFalse("Button must immediately disable",button.isEnabled());assertEquals("Составляем блюда…",button.getText().toString());View status=root().findViewWithTag("selection-feedback");assertNotNull(status);assertEquals(View.VISIBLE,status.getVisibility());assertFalse(((TextView)status).getText().toString().isEmpty());button.performClick();gate.countDown();idleUntil(()->!busy());assertEquals(1,sent.size());assertEquals("plan",sent.get(0).getString("mode"));assertFalse(sent.get(0).has("images"));}
 @Test public void failedRequestCanBeRetriedWithFreshIdAndNoPhotos()throws Exception{review();java.util.concurrent.atomic.AtomicInteger opened=new java.util.concurrent.atomic.AtomicInteger();ApiClient.configureForTests(url->response(url,opened.incrementAndGet()==1?"{\"status\":\"failed\",\"error\":\"Тестовая ошибка JSON\"}":done()));find(root(),"Всё верно — составить блюда").performClick();idleUntil(()->!busy());TextView button=find(root(),"Всё верно — составить блюда");assertNotNull(button);assertTrue(button.isEnabled());TextView feedback=root().findViewWithTag("selection-feedback");assertNotNull(feedback);assertTrue(feedback.getText().toString().contains("Тестовая ошибка JSON"));assertTrue(prefs.contains("reviewedInventory"));assertFalse(prefs.contains(SelectionClient.PENDING));button.performClick();idleUntil(()->!busy());assertEquals(2,sent.size());assertNotEquals(sent.get(0).getString("requestId"),sent.get(1).getString("requestId"));assertFalse(sent.get(1).has("images"));assertNotNull(find(root(),"Рис с томатами"));assertFalse(prefs.contains("reviewedInventory"));}
 @Test public void leftoverRecognizedReadyDoesNotSwallowExplicitPlanClick()throws Exception{review();prefs.edit().putString(SelectionClient.READY,inventory()).commit();ApiClient.configureForTests(url->response(url,done()));find(root(),"Всё верно — составить блюда").performClick();idleUntil(()->!busy());assertEquals("Plan click must send exactly one text-only request",1,sent.size());assertNotNull(find(root(),"Рис с томатами"));}
 @Test public void savedFailedJobUsesGetThenNextExplicitTapCreatesOnlyOneNewPlan()throws Exception{review();prefs.edit().putString(SelectionClient.PENDING,"saved-failed-selection-123456").commit();java.util.concurrent.atomic.AtomicInteger gets=new java.util.concurrent.atomic.AtomicInteger();ApiClient.configureForTests(url->{if(url.getPath().endsWith("saved-failed-selection-123456")){gets.incrementAndGet();return response(url,"{\"status\":\"failed\",\"error\":\"Прежний подбор завершился ошибкой\"}");}return response(url,done());});find(root(),"Всё верно — составить блюда").performClick();idleUntil(()->!busy());assertEquals(1,gets.get());assertEquals(0,sent.size());assertFalse(prefs.contains(SelectionClient.PENDING));assertTrue(prefs.contains("reviewedInventory"));find(root(),"Всё верно — составить блюда").performClick();idleUntil(()->!busy());assertEquals(1,sent.size());assertEquals("plan",sent.get(0).optString("mode"));assertFalse(sent.get(0).has("images"));}
 @Test public void completedRecipeResultIsOpenedWithoutAnotherPaidRequest()throws Exception{review();prefs.edit().putString(SelectionClient.READY,new JSONObject(done()).getJSONObject("result").toString()).commit();ApiClient.configureForTests(url->{throw new AssertionError("Completed recipes must not be resent");});find(root(),"Всё верно — составить блюда").performClick();idleUntil(()->!busy());assertNotNull(find(root(),"Рис с томатами"));assertFalse(prefs.contains(SelectionClient.READY));assertEquals(0,sent.size());}


 @Test public void legacyPhotoFailureKeepsReviewedListAndNeverSendsPhotos()throws Exception{review();ApiClient.configureForTests(url->response(url,"{\"status\":\"done\",\"result\":{\"kind\":\"plan\",\"status\":\"not_food\",\"recipe\":{\"status\":\"not_food\",\"message\":\"Снимите продукты на столе.\"}}}"));find(root(),"Всё верно — составить блюда").performClick();idleUntil(()->!busy());assertTrue(prefs.contains("reviewedInventory"));assertNotNull(find(root(),"Проверьте продукты"));assertNotNull(find(root(),"Томаты"));assertNull(find(root(),"Снимите продукты на столе."));assertTrue(find(root(),"Всё верно — составить блюда").isEnabled());assertFalse(prefs.contains(SelectionClient.READY));assertFalse(sent.get(0).has("images"));}
 @Test public void safetyClarificationStaysOnReviewWithRetryAction()throws Exception{review();ApiClient.configureForTests(url->response(url,"{\"status\":\"done\",\"result\":{\"kind\":\"plan\",\"status\":\"need_details\",\"recipe\":{\"status\":\"need_details\",\"message\":\"Уточните вид грибов.\"}}}"));find(root(),"Всё верно — составить блюда").performClick();idleUntil(()->!busy());assertTrue(prefs.contains("reviewedInventory"));assertNotNull(find(root(),"Проверьте продукты"));assertEquals("Уточните вид грибов.",((TextView)root().findViewWithTag("selection-feedback")).getText().toString());assertTrue(find(root(),"Всё верно — составить блюда").isEnabled());assertFalse(prefs.contains(SelectionClient.READY));}
}
